function parseBandwidth(str){
  var s=String(str||'').toLowerCase().replace(/\s+/g,'');
  var m=s.match(/^([\d.]+)([kmg]?)b/);
  if(!m) return null;
  var n=parseFloat(m[1]);
  if(!isFinite(n)||n<=0) return null;
  var mult={k:1e3,m:1e6,g:1e9}[m[2]]||1;
  return n*mult;
}
function fmtBytes(n){
  if(!isFinite(n)) return '-';
  var units=['B','KiB','MiB','GiB','TiB'], i=0;
  while(n>=1024&&i<units.length-1){n/=1024;i++;}
  return (n>=100? Math.round(n): Math.round(n*100)/100)+' '+units[i];
}
function fmtBits(bps){
  if(!isFinite(bps)) return '-';
  var units=['bps','Kbps','Mbps','Gbps'], i=0;
  while(bps>=1000&&i<units.length-1){bps/=1000;i++;}
  return (bps>=100? Math.round(bps): Math.round(bps*100)/100)+' '+units[i];
}
function calcBdp(o){
  o=o||{};
  var bw=(typeof o.bandwidthBps==='number')? o.bandwidthBps : parseBandwidth(o.bandwidth);
  if(!bw||bw<=0) return {error:'带宽无法解析（示例：1Gbps、100Mbps、500Kbps）'};
  var rtt=parseFloat(o.rttMs);
  if(!isFinite(rtt)||rtt<=0) return {error:'RTT 须为正数（毫秒）'};
  var rttSec=rtt/1000;
  var bdpBytes=bw*rttSec/8;
  var win=parseFloat(o.windowBytes);
  var hasWin=isFinite(win)&&win>0;
  var payload=parseFloat(o.payloadBytes);
  var hasPayload=isFinite(payload)&&payload>0;
  var res={
    bandwidthBps:bw, bandwidthHuman:fmtBits(bw), rttMs:rtt,
    bdpBytes:bdpBytes, bdpHuman:fmtBytes(bdpBytes),
    windowBytes:hasWin?win:null, windowHuman:hasWin?fmtBytes(win):null,
    windowSufficient:hasWin? win>=bdpBytes : null,
    utilizationPct:hasWin? Math.round(win/bdpBytes*10000)/100 : null,
    windowLimitedBps:hasWin? win*8/rttSec : null,
    windowLimitedHuman:hasWin? fmtBits(win*8/rttSec) : null,
    idealTransferSec:hasPayload? payload*8/bw : null,
    transferRttCount:(hasPayload&&hasWin)? Math.ceil(payload/win) : null,
    effectiveTransferSec:(hasPayload&&hasWin)? Math.ceil(payload/win)*rttSec : null
  };
  if(!hasWin){
    res.verdict='未填窗口：BDP 即跑满带宽所需的最低在途字节数（TCP 收发缓冲合计应不小于它）';
  } else if(win>=bdpBytes){
    res.verdict='✓ 窗口充足（'+fmtBytes(win)+' ≥ BDP '+fmtBytes(bdpBytes)+'），可充分利用带宽';
  } else {
    res.verdict='× 窗口不足：吞吐被限制在约 '+fmtBits(win*8/rttSec)+'（带宽利用率仅 '+res.utilizationPct+'%）';
  }
  return res;
}
function bdpTable(bandwidthBps, rttList){
  var bw=bandwidthBps;
  if(!bw||bw<=0) return [];
  return (rttList||[10,50,100,200]).map(function(rtt){
    var b=bw*(rtt/1000)/8;
    return {rttMs:rtt, bdpBytes:b, bdpHuman:fmtBytes(b)};
  });
}
var EXPORTS={parseBandwidth:parseBandwidth, fmtBytes:fmtBytes, fmtBits:fmtBits, calcBdp:calcBdp, bdpTable:bdpTable};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BdpForgePure = EXPORTS; }
